export function openLive(opts: LiveOptions): LiveSocket {
  const Impl = opts.WebSocketImpl ?? (typeof WebSocket !== "undefined" ? WebSocket : undefined);
  const wait = opts.wait ?? realWait;
  let socket: WebSocket | null = null;
  let watching: string | null = null;
  let attempt = 0;
  let closed = false;
  let open = false;
  let cancelWait: (() => void) | null = null;
  let keepalive: ReturnType<typeof setInterval> | null = null;

  const stopKeepalive = () => {
    if (keepalive) {
      clearInterval(keepalive);
      keepalive = null;
    }
  };

  const setOpen = (value: boolean) => {
    if (open === value) return;
    open = value;
    opts.onState?.(value);
  };

  const send = () => {
    if (open && socket && watching) socket.send(JSON.stringify({ t: "watch", id: watching }));
  };

  const connect = async () => {
    if (closed || !Impl) return;
    let url: string;
    try {
      url = await opts.url();
    } catch {
      // No token: nobody to be. Try again later; the account may come back.
      schedule();
      return;
    }
    if (closed) return;
    let ws: WebSocket;
    try {
      ws = new Impl(url);
    } catch {
      schedule();
      return;
    }
    socket = ws;
    ws.onopen = () => {
      if (ws !== socket) return;
      attempt = 0;
      setOpen(true);
      send();
      keepalive = setInterval(() => {
        if (ws !== socket) return;
        ws.send(JSON.stringify({ t: "ping" }));
      }, KEEPALIVE_MS);

